import { CheckIcon } from "@/components/icons";
import { PIPELINE_STEPS } from "@/constants";
import { cn } from "@/lib/utils";

interface PipelineViewProps {
  currentStepIndex: number; // index into PIPELINE_STEPS, -1 = not started
}

export function PipelineView({ currentStepIndex }: PipelineViewProps) {
  return (
    <div className="pipeline">
      {PIPELINE_STEPS.map((step, i) => {
        const isComplete = i < currentStepIndex;
        const isCurrent = i === currentStepIndex;
        return (
          <div key={step.id} className="pipeline-row">
            <div className="pipeline-node-col">
              <div
                className={cn(
                  "pipeline-node",
                  isComplete && "pipeline-node--complete",
                  isCurrent && "pipeline-node--current"
                )}
              >
                {isComplete ? <CheckIcon size={14} /> : i + 1}
              </div>
              {i < PIPELINE_STEPS.length - 1 && (
                <div className={cn("pipeline-line", isComplete && "pipeline-line--complete")} />
              )}
            </div>
            <div className="pipeline-body">
              <p className={cn("pipeline-label", (isComplete || isCurrent) && "pipeline-label--active")}>
                {step.label}
              </p>
              {isCurrent && <p className="pipeline-sub pipeline-sub--current">In progress...</p>}
              {isComplete && <p className="pipeline-sub">Complete</p>}
            </div>
          </div>
        );
      })}
    </div>
  );
}
