"use client";

import { useState } from "react";
import { AppShell } from "@/components/shared/AppShell";
import { UploadBox } from "@/components/upload/UploadBox";
import { DocumentCard } from "@/components/upload/DocumentCard";
import { PipelineView } from "@/components/upload/PipelineView";
import { ProgressBar } from "@/components/ui/ProgressBar";
import { EmptyState } from "@/components/ui/EmptyState";
import { Card } from "@/components/ui/Card";
import { useDocuments } from "@/hooks/useDocuments";
import { uploadDocument } from "@/services/api";
import { useToast } from "@/components/ui/Toast";
import { FileStackIcon } from "@/components/icons";

export default function UploadPage() {
  const { documents, remove, addDocument } = useDocuments();
  const toast = useToast();
  const [isUploading, setIsUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [pipelineStep, setPipelineStep] = useState(-1);
  const [currentFile, setCurrentFile] = useState<string | null>(null);

  async function handleFiles(files: File[]) {
    const file = files[0];
    if (!file) return;

    setIsUploading(true);
    setCurrentFile(file.name);
    setProgress(0);
    setPipelineStep(0);

    const doc = await uploadDocument(file, (p) => setProgress(p));

    const stages = [1, 2, 3, 4, 5];
    for (const stage of stages) {
      await new Promise((r) => setTimeout(r, 500));
      setPipelineStep(stage);
    }

    addDocument(doc);
    toast.success(`${file.name} processed and indexed`);
    setIsUploading(false);
    setPipelineStep(-1);
    setCurrentFile(null);
  }

  return (
    <AppShell title="Upload">
      <div className="grid-two">
        <div style={{ display: "flex", flexDirection: "column", gap: "1.5rem" }}>
          <UploadBox onFilesSelected={handleFiles} />

          {isUploading && (
            <Card hoverLift={false}>
              <p className="truncate" style={{ fontSize: "0.875rem", fontWeight: 500, color: "#374151" }}>
                {currentFile}
              </p>
              <div className="mt-6" style={{ marginTop: "0.75rem" }}>
                <ProgressBar value={progress} />
              </div>
              <div style={{ marginTop: "1.5rem" }}>
                <PipelineView currentStepIndex={pipelineStep} />
              </div>
            </Card>
          )}

          <div>
            <h2 className="section-title">Upload History</h2>
            {documents.length === 0 ? (
              <EmptyState
                icon={<FileStackIcon size={24} />}
                title="No documents yet"
                description="Upload your first PDF or TXT file to start building your knowledge base."
              />
            ) : (
              <div className="grid-docs">
                {documents.map((doc) => (
                  <DocumentCard key={doc.id} document={doc} onDelete={remove} />
                ))}
              </div>
            )}
          </div>
        </div>

        <div>
          <Card hoverLift={false}>
            <h3 className="section-title">Tips for best results</h3>
            <ul className="tips-list">
              <li>Use text-based PDFs rather than scanned images.</li>
              <li>Split very large files by chapter for cleaner chunking.</li>
              <li>Descriptive filenames help you find documents later.</li>
            </ul>
          </Card>
        </div>
      </div>
    </AppShell>
  );
}
