import { FileTextIcon, TrashIcon, EyeIcon, LoaderIcon } from "@/components/icons";
import { Card } from "@/components/ui/Card";
import { formatDate } from "@/lib/utils";
import type { StudyDocument } from "@/types";

interface DocumentCardProps {
  document: StudyDocument;
  onDelete: (id: string) => void;
  onView?: (id: string) => void;
}

const statusBadgeClass: Record<StudyDocument["status"], string> = {
  ready: "badge badge--success",
  processing: "badge badge--pink",
  failed: "badge badge--danger",
};

const statusLabel: Record<StudyDocument["status"], string> = {
  ready: "Ready",
  processing: "Processing",
  failed: "Failed",
};

export function DocumentCard({ document, onDelete, onView }: DocumentCardProps) {
  return (
    <Card className="doc-card">
      <div className="doc-card-top">
        <div className="doc-icon">
          <FileTextIcon size={20} />
        </div>
        <div style={{ minWidth: 0, flex: 1 }}>
          <p className="doc-name truncate">{document.name}</p>
          <p className="doc-meta">
            {formatDate(document.uploadedAt)} · {document.sizeLabel}
          </p>
        </div>
      </div>

      <div className="doc-status-row">
        <span className={statusBadgeClass[document.status]}>
          {document.status === "processing" && <LoaderIcon size={12} />}
          {statusLabel[document.status]}
        </span>
        <span className="doc-chunks">{document.chunkCount} chunks</span>
      </div>

      <div className="doc-actions">
        <button onClick={() => onView?.(document.id)} className="doc-action-btn">
          <EyeIcon size={14} /> View
        </button>
        <button onClick={() => onDelete(document.id)} className="doc-action-btn doc-action-btn--danger">
          <TrashIcon size={14} /> Delete
        </button>
      </div>
    </Card>
  );
}
